-- seoul: checked place by place on 2026-10-25 (still open, own websites, prices with sources).

UPDATE "Place" p SET "website" = 'https://www.fourseasons.com/seoul/' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'seoul' AND p.slug = 'four-seasons-hotel-seoul';
UPDATE "Place" p SET "website" = 'https://www.ihg.com/holidayinnexpress/hotels/us/en/seoul/seohg/hoteldetail' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'seoul' AND p.slug = 'holiday-inn-express-seoul-hongdae';
UPDATE "Place" p SET "closed" = true, "tip" = 'Reported permanently closed (KoreaToDo; Grrrl Traveler, 2026).' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'seoul' AND p.slug = 'siloam-sauna';
UPDATE "Place" p SET "name" = 'Starfield COEX Mall' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'seoul' AND p.slug = 'coex-mall';
UPDATE "Place" p SET "tip" = 'Residents painted over the famous flower and koi stair murals in 2016; it is a lived-in neighbourhood, so keep the noise down.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'seoul' AND p.slug = 'ihwa-mural-village';
UPDATE "Place" p SET "checkedAt" = '2026-10-25' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'seoul' AND p.slug IN ('four-seasons-hotel-seoul', 'holiday-inn-express-seoul-hongdae', 'siloam-sauna', 'apgujeong-rodeo', 'bukchon-hanok-village', 'bukhansan-national-park', 'changdeokgung-palace', 'changgyeonggung-palace', 'cheonggyecheon-stream', 'coex-mall', 'deoksugung-palace', 'dmz-tour', 'dongdaemun-design-plaza', 'ewha-womans-university', 'guerlain-spa-shilla', 'gwanghwamun-square', 'gyeongbokgung-palace', 'hanboknam-gyeongbokgung', 'hongdae', 'ihwa-mural-village', 'inwangsan', 'jogyesa-temple', 'jongmyo-shrine', 'lotte-world-adventure', 'lotte-world-tower-seoul-sky', 'mmca-seoul', 'n-seoul-tower', 'nami-island', 'tapgol-park', 'trickeye-museum-seoul', 'cafe-comma-hapjeong', 'chatteul-tea-house', 'common-ground', 'gwangjang-market', 'insadong', 'jihwaja', 'jongno-pojangmacha', 'myeongdong');

UPDATE "Item" SET "priceCents" = 250, "priceNote" = 'street snacks ₩3,500–5,000', "priceSourceUrl" = 'https://www.tunextravels.com/best-korean-street-foods-to-try-2025-guide-korean-street-foods/', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'seoul-3-days-thebrokebackpacker--myeongdong' AND "priceCents" IS NULL;
UPDATE "Item" SET "priceCents" = 857, "priceNote" = '₩12,000 adult entry', "priceSourceUrl" = 'https://thesoulofseoul.net/trickeye-museum-revamped/', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'seoul-3-days-thebrokebackpacker--trickeye-museum-seoul' AND "priceCents" IS NULL;
UPDATE "Item" SET "priceCents" = 714, "priceNote" = '₩10,000 pass for all exhibitions', "priceSourceUrl" = 'https://www.mmca.go.kr/eng/visitingInfo/seoulInfo.do', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'seoul-3-days-bucketlistly--national-museum-of-modern-and-contemporary-art-seoul' AND "priceCents" IS NULL;
UPDATE "Item" SET "priceCents" = 357, "priceNote" = 'bindaetteok ₩5,000', "priceSourceUrl" = 'https://koreaexperience.com/blog/gwangjang-market-complete-food-guide', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'seoul-3-days-theplanetd--gwangjang-market' AND "priceCents" IS NULL;
UPDATE "Item" SET "priceCents" = 7857, "priceNote" = 'courses ₩110,000–175,000', "priceSourceUrl" = 'https://ordinarypatrons.com/2025/04/11/jihwaja-seoul-restaurant-royal-korean-court-cuisine/', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'seoul-6-days-luxury-foratravel--jihwaja' AND "priceCents" IS NULL;
UPDATE "Item" SET "priceCents" = 2500, "priceNote" = 'about ₩35,000 a person with drinks', "priceSourceUrl" = 'https://koreaexperience.com/blog/pojangmacha-street-tent-bars-experience', "priceCheckedAt" = '2026-10-25' WHERE "id" = 'seoul-6-days-luxury-foratravel--jongno-3-ga-pojangmacha-street' AND "priceCents" IS NULL;
-- Checked: no source publishes a price for these.
UPDATE "Item" SET "priceCheckedAt" = '2026-10-25' WHERE "priceCents" IS NULL AND "id" IN ('seoul-3-days-bucketlistly--cafe-comma', 'seoul-3-days-bucketlistly--dmz-half-day-tour', 'seoul-3-days-theplanetd--hongdae', 'seoul-6-days-luxury-foratravel--chatteul-tea-house', 'seoul-6-days-luxury-foratravel--guerlain-spa-the-shilla-seoul', 'seoul-6-days-luxury-foratravel--butterfinger-pancakes');
